'use strict';
window.RUN=()=>{const t=T,L=t.BattleLab,P=t.P,G=t.G,o=[],ok=(c,m)=>o.push((c?'PASS ':'FAIL ')+m),rng=Math.random;try{
 t.begin('soldier');G.mode='world';G.modal=false;t.hidePanel();
 L.start({leftGroups:[{type:'hum_foot',count:2,name:'<script>literal</script>'},{type:'hum_foot',count:2,name:'Second'},{type:'hero',count:1}],rightGroups:[{type:'hum_foot',count:2,name:'Enemy'}],deploy:false,paused:true,ai:false,seed:731});let b=t.B,ids=t.playerGroups(),tele=L.session.telemetry,source=b.units.find(u=>u.grp===ids[0]),hero=b.hero,enemy=b.units.filter(u=>u.team===1),target=enemy[0];
 ok(Object.keys(tele.groups).length===4&&ids[0]!==ids[1]&&tele.groups[ids[0]].roster.length===2,'initial telemetry preserves duplicate-type groups as separate rosters');
 b.hx.inv=0;const before=tele.groups[ids[0]].damageDealt;t.applyDmg(target,5,1,0,source);ok(tele.groups[ids[0]].damageDealt-before===5&&tele.groups[target.grp].damageTaken===5,'sourced damage credits attacker and target group');
 target.hp=3;const pre=tele.groups[ids[0]].damageDealt;t.applyDmg(target,99,1,0,source);ok(tele.groups[ids[0]].damageDealt-pre===3&&tele.groups[ids[0]].kills===1,'damage is capped at remaining HP and actual lethal hit earns one kill');
 const dealt=tele.groups[ids[0]].damageDealt;t.applyDmg(target,99,1,0,source);ok(tele.groups[ids[0]].damageDealt===dealt&&tele.groups[ids[0]].kills===1,'already-dead target remains excluded from telemetry');
 const dodgeTarget=enemy[1];dodgeTarget.ch={inv:1};const prior=tele.groups[ids[0]].damageDealt;t.applyDmg(dodgeTarget,20,1,0,source);ok(tele.groups[ids[0]].damageDealt===prior,'dodge/invulnerability produces no effective damage credit');delete dodgeTarget.ch;
 const second=b.units.find(u=>u.grp===ids[1]);t.applyDmg(second,4,1,0,null);ok(tele.uncredited.damageTaken===0&&tele.uncredited.damageDealt===4,'missing sources are explicitly recorded as uncredited');
 const target2=enemy[1],meleeBefore=tele.groups[ids[0]].damageDealt;target2.hp=target2.max;t.hit(source,target2,8);ok(tele.groups[ids[0]].damageDealt>meleeBefore&&tele.groups[target2.grp].damageTaken>0,'normal melee hit attributes effective damage through the shared attack path');
 const heroBefore=tele.groups[ids[2]].damageDealt;target2.hp=target2.max;t.heroHit(target2,1,{});ok(tele.groups[ids[2]].damageDealt>heroBefore,'manual hero hit credits its hero group');
 target.hp=target.max;target2.hp=target2.max;target2.x=target.x=200;target2.y=target.y=200;const shotBefore=tele.groups[ids[0]].damageDealt,hp1=target.hp,hp2=target2.hp;source.s={...source.s,magic:true,splash:30,splashMul:.5};b.arrows.push({by:source,team:source.team,src:source.s,dmg:20,x:target2.x-1,y:target2.y-6,vx:0,vy:0,life:1,magic:true,col:'#fff'});t.updateProjectiles(.01);ok(tele.groups[ids[0]].damageDealt>shotBefore&&target.hp<hp1&&target2.hp<hp2,'projectile direct and splash impacts retain the firing group as source');
 b.t=1.25;L.sampleMorale();ok(tele.groups[ids[0]].morale.length===2&&tele.groups[ids[0]].morale[1].time===1.25,'morale history records initial and timed group samples');
 t.rout(source);ok(tele.groups[ids[0]].events.some(e=>e.type==='routed'&&e.time===1.25),'route event includes combat-clock timestamp');
 const killsBeforeExit=tele.groups[ids[0]].kills;t.leaveField(source);t.leaveField(second);ok(tele.groups[ids[0]].kills===killsBeforeExit&&tele.groups[ids[0]].events.some(e=>e.type==='field_exit'&&e.cause==='routed')&&tele.groups[ids[1]].events.some(e=>e.type==='field_exit'&&e.cause==='withdrawn'),'routed and ordered field departures are separate from death and do not add kills');
 b.groups[ids[1]].withdraw();ok(tele.groups[ids[1]].events.some(e=>e.type==='withdraw_order'&&e.time===1.25),'withdrawal order records its transition timestamp');
 const sim=b.t;L.step(2);ok(b.t>sim&&b.paused,'stepping advances the combat clock and pauses afterward');
 const serial=JSON.stringify(L.report());ok(!serial.includes('"unit":')&&serial.includes('"config"')&&serial.includes('"seed":731'),'report is serializable and carries canonical config and seed without unit object links');
 const oldEvent=L.eventLimit,oldMorale=L.moraleLimit;L.eventLimit=1;L.moraleLimit=1;for(let i=0;i<3;i++)L.event('routed',source);for(let i=0;i<4;i++){b.t+=2;L.sampleMorale()}L.eventLimit=oldEvent;L.moraleLimit=oldMorale;ok(tele.groups[ids[0]].truncated.events>0&&tele.groups[ids[0]].truncated.morale>0,'event and morale histories remain bounded with truncation counts');
 b.win=true;L.finish();const final=L.report(),live=b.units.find(u=>!u.left&&u.hp>0),savedHp=final.final.units.find(u=>u.id===live.id).hpLeft,savedDamage=final.groups[ids[0]].damageDealt;live.hp=0;tele.groups[ids[0]].damageDealt+=50;final.groups[ids[0]].damageDealt=0;final.final.units[0].hpLeft=123;const frozen=L.report();ok(frozen.final.result==='Left side wins'&&frozen.groups[ids[0]].final.survivors>=0&&frozen.groups[ids[0]].final.dead>=0&&frozen.final.units.find(u=>u.id===live.id).hpLeft===savedHp&&frozen.groups[ids[0]].damageDealt===savedDamage,'completed report freezes metrics and a defensive final snapshot');
 Dshow();L.restart();ok(L.session.telemetry.groups[ids[0]].damageDealt===0&&L.session.telemetry.groups[ids[0]].events.length===0,'restart clears diagnostics while retaining the same configuration and seed');L.exit();
 L.start({leftGroups:[{type:'hum_foot',count:1}],rightGroups:[{type:'hum_foot',count:1}],deploy:true,paused:true,seed:731});b=t.B;const samples=L.session.telemetry.groups[t.playerGroups()[0]].morale.length;try{L.step(1)}catch(e){}L.sampleMorale();ok(b.t===0&&L.session.telemetry.groups[t.playerGroups()[0]].morale.length===samples,'deployment pause does not advance combat time or periodic morale history');L.exit();
 }catch(e){o.push('EXC '+e.message+' '+e.stack)}finally{if(L.active)L.exit();Math.random=rng}
 const d=document.createElement('pre');d.id='OUT';d.textContent=o.concat(ERR.map(e=>'ERR '+e)).join('\n');document.body.appendChild(d);
 function Dshow(){const d=t.DevConsole;d.show('report');const host=d.root.querySelector('[data-lab-report-content]');ok(host.textContent.includes('Left side')&&host.textContent.includes('Right side')&&host.textContent.includes('<script>literal</script>')&&!host.querySelector('script'),'report renders both sides and treats custom labels as text');d.close()}
};
